import { Frame, Group, PlacedItem } from "./tokens";

/**
 * 模板里的组：部件自带坐标
 *
 * 和市场的组件数据一样 —— 一组部件是"摆好了的"，位置就在部件上。
 * 画布的渲染读的也是这个形状。
 */
export type TemplateGroup = Omit<Group, "items"> & { items: PlacedItem[] };
export type TemplateScreens = { frames: Frame[]; groups: TemplateGroup[] };

/**
 * 模板
 * ---------------------------------------------------------------------------
 * 一个模板就是「一整套屏幕」：农场有五个页面，就一次给你五个，而不是让你一屏一屏地搭。
 *
 * 模板存在浏览器里（和文档、AI 设置一样，没有服务端），内置的那个随代码走。
 * 「新建模板」会把当前画布上的屏幕存成新的一条；之后点开哪条模板，画布就换成它的屏幕。
 */
export type Template = {
  id: string;
  name: string;
  /** 内置模板：跟着代码走，不能删 */
  builtin?: boolean;
  /** 建立时间；内置的没有 */
  at?: number;
  /** 来自本地：自己建的，或者对某条内置模板的本地覆盖 */
  custom?: boolean;
  /** 这个模板包含的屏幕 */
  screens: TemplateScreens;
};

const KEY = "m3e:templates";

/** 一屏的名字与它的左上角：模板里的屏幕从左往右排开 */
const PHONE_W = 412;
const PHONE_H = 892;
const GAP_X = 120;

