/** 内置模板：排在最前面，删不掉 */
export const BUILTIN_TEMPLATES: Template[] = [QQ_FARM];
/* ==== 内置模板结束 ==== */

const isRecord = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);

/** 至少要有屏幕才敢往画布上放；「全新的空白屏幕」本来就没有组，所以组可以是空的 */
const readScreens = (v: unknown): TemplateScreens | null => {
  if (!isRecord(v)) return null;
  const frames = Array.isArray(v.frames) ? (v.frames as Frame[]).filter((f) => isRecord(f) && typeof f.id === "string") : [];
  const groups = Array.isArray(v.groups) ? (v.groups as TemplateGroup[]).filter((g) => isRecord(g) && Array.isArray(g.items)) : [];
  if (frames.length === 0) return null;
  return { frames, groups };
};

const readTemplate = (v: unknown): Template | null => {
  if (!isRecord(v)) return null;
  const screens = readScreens(v.screens);
  if (!screens) return null;
  const name = typeof v.name === "string" ? v.name.trim() : "";
  if (!name) return null;
  return {
    id: typeof v.id === "string" && v.id ? v.id : uid(),
    name,
    ...(typeof v.at === "number" ? { at: v.at } : undefined),
    ...(v.custom === true ? { custom: true } : undefined),
    screens,
  };
};

/** 一个够用的短 id：模板只在本地存，不需要全局唯一 */
export const uid = () => Math.random().toString(36).slice(2, 10);

/** 使用者自己建的模板，从新到旧 */
export function loadTemplates(): Template[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const list: unknown = JSON.parse(raw);
    if (!Array.isArray(list)) return [];
    return list
      .map(readTemplate)
      .filter((t): t is Template => !!t)
      .sort((a, b) => (b.at ?? 0) - (a.at ?? 0));
  } catch {
    return [];
  }
}

export function saveTemplates(list: Template[]) {
  try {
    localStorage.setItem(KEY, JSON.stringify(list));
  } catch {}
}

/**
 * 面板上要显示的模板：内置的在前，自己建的接在后面
 *
 * `mine` 里如果有一条和内置模板**同一个 id**，那它是这份内置模板的本地覆盖
 * （用「保存」换掉了内置的那一套屏幕）：内置的那条不再单独出现，位置仍按内置的次序排。
 */
export const allTemplates = (mine: Template[]): Template[] => {
  const overridden = new Set(mine.map((t) => t.id));
  return [
    ...BUILTIN_TEMPLATES.filter((b) => !overridden.has(b.id)),
    /* 覆盖的那一条仍然显示"内置"：它删不掉，只能被下一次保存覆盖 */
    ...mine.map((t) => (BUILTIN_TEMPLATES.some((b) => b.id === t.id) ? { ...t, builtin: true } : t)),
  ];
};

/** 内置模板的本地覆盖，`mine` 里 id 对上的那一条 */
export const overrideOf = (mine: Template[], id: string): Template | undefined => mine.find((t) => t.id === id);

/**
 * 把一份模板变成能直接交给画布的屏幕
 *
 * 每次取用都克隆一份，并重新分配 id：同一个模板放两次不该打架，
 * 之后你在画布上怎么改也不会回头改到模板。
 */
export function screensOf(t: Template, nextId: () => string = uid): { frames: Frame[]; groups: Group[] } {
  const map = new Map<string, string>();
  const frames = t.screens.frames.map((f) => {
    const id = nextId();
    map.set(f.id, id);
    return { ...f, id };
  });
  const groups: Group[] = restoreGroups(t.screens.groups).map((g) => ({
    ...g,
    id: nextId(),
    /* 屏幕 id 换过了，组上的归属也要跟着换 */
    ...(g.frameId && map.has(g.frameId) ? { frameId: map.get(g.frameId) } : undefined),
    items: (g.items as PlacedItem[]).map((it) => ({ ...it, id: nextId() })),
  }));
  return { frames, groups };
}

/** 一个模板里有多少屏；面板上要显示 */
export const screenCount = (t: Template) => t.screens.frames.length;

/** 一台「全新的空白屏幕」：新模板就是这样开始的 */
export function blankScreen(nextId: () => string = uid): TemplateScreens {
  return { frames: [{ id: nextId(), name: "首页", x: 0, y: 0, w: PHONE_W, h: PHONE_H }], groups: [] };
}

/**
 * 把画布上的组存进模板
 *
 * 画布上「连排组」里的部件坐标是相对组原点的，模板里统一成全局坐标 ——
 * 这样一份模板读出来就能直接摆到画布上，不必先猜它是哪一种形态。
 * 手摆的组（`free`）本来就各自带偏移，原样带走。
 */
export function captureGroups(groups: Group[]): TemplateGroup[] {
  return groups.map((g) => ({
    ...g,
    x: Math.round(g.x),
    y: Math.round(g.y),
    items: (g.items as PlacedItem[]).map((it) =>
      g.free ? it : { ...it, x: (it.x ?? 0) + g.x, y: (it.y ?? 0) + g.y },
    ),
  }));
}

/** 反过来：把模板里的组摆到画布上（全局 → 相对组原点） */
export function restoreGroups(groups: TemplateGroup[]): Group[] {
  return groups.map((g) => ({
    ...g,
    items: g.items.map((it) => (g.free ? it : { ...it, x: (it.x ?? 0) - g.x, y: (it.y ?? 0) - g.y })),
  }));
}
